// through {{key}} placeholders. Citations are written [@key] or [@a;@b].
const fs = require("fs");
const L = require("./lib");
const { d, h1, h2, table, rule, ref } = L;
const { Document, Packer, Paragraph, TextRun, AlignmentType, PageBreak, ImageRun,
        convertInchesToTwip, Footer, PageNumber } = d;

const REFS = JSON.parse(fs.readFileSync("refs.json", "utf8"));
const FACTS = JSON.parse(fs.readFileSync("facts_v6.json", "utf8"));
const used = new Set();

// No number may be typed in this file: every number in the text comes from
// facts_v6.json. After removing {{keys}}, citations, list numbering, formulas
// ($...$) and names or labels that contain digits (M19, ResNet-18, Table S2b,
// Fig. 1a, CO2Wounds-V2, 2D), no digit may remain.
const LABEL = /(?:Figs?\.|Tables?|Online Resource) S?\d+[a-z]?|\bS\d+[a-z]?\b|\b[A-Za-z][A-Za-z+-]*\d[\w.+-]*|\b2D\b/g;
function checkDigits(text) {
  const t = text.replace(/\{\{[^}]+\}\}/g, "").replace(/\[@[^\]]+\]/g, "").replace(/^\d+\. /, "")
    .replace(/\$[^$]*\$/g, "").replace(/\^\{[a-z]\}/g, "").replace(LABEL, "");
  const m = t.match(/\d/);
  if (m) throw new Error("number typed by hand: ..." + t.slice(Math.max(0, m.index - 60), m.index + 40));
}

function S(text) {
  checkDigits(text);
  const out = text.replace(/\{\{([^}]+)\}\}/g, (_, k) => {
    if (!FACTS[k]) throw new Error("missing fact " + k);
    used.add(k);
    return FACTS[k].v;
  });
  if (out.includes("—")) throw new Error("em dash in: " + out.slice(0, 80));
  if (/(^|[\s(])-\d/.test(out)) throw new Error("ASCII minus before a number in: " + out.slice(0, 120));
  return out;
}

const order = [];
function cite(text) {
  return text.replace(/\[(@[^\]]+)\]/g, (_, inner) => {
    const keys = inner.split(";").map(s => s.trim().replace(/^@/, ""));
    const nums = keys.map(k => {
      if (!REFS[k]) throw new Error("unknown reference " + k);
      if (!order.includes(k)) order.push(k);
      return order.indexOf(k) + 1;
    }).sort((a, b) => a - b);
    const parts = [];
    for (let i = 0; i < nums.length; i++) {
      let j = i;
      while (j + 1 < nums.length && nums[j + 1] === nums[j] + 1) j++;
      parts.push(j - i >= 2 ? `${nums[i]}–${nums[j]}` : nums.slice(i, j + 1).join(", "));
      i = j;
    }
    return "[" + parts.join(", ") + "]";
  });
}

// word counts per part of the paper
let part = "front";
const words = {};
function count(t) {
  const n = t.replace(/\*\*/g, "").replace(/\[[\d,\s–]+\]/g, "").split(/\s+/).filter(w => /[A-Za-z0-9]/.test(w)).length;
  words[part] = (words[part] || 0) + n;
}

const B = [];
const add = (...xs) => xs.forEach(x => B.push(x));
const P = (t, o) => { const s = cite(S(t)); count(s); add(L.p(s, o)); };
const cap = (kind, n, t) => add(L.caption(kind, n, cite(S(t))));
const T = (head, rows, widths, opts) => add(table(head.map(S),
  rows.map(r => (r && r.section !== undefined) ? { section: S(r.section) } : r.map(S)), widths, opts));
const H1 = t => add(h1(t));
const H2 = t => add(h2(t));
const list = (items, numbered = true) => items.forEach((t, i) =>
  P(numbered ? `${i + 1}. ${t}` : t, { indent: { left: 240 }, after: 80 }));

function fig(file, wmm) {
  const px = require("child_process").execSync(`python3 -c "from PIL import Image;i=Image.open('${file}');print(i.size[0],i.size[1])"`).toString().trim().split(" ").map(Number);
  const w = Math.round(wmm / 25.4 * 96);
  add(new Paragraph({ alignment: AlignmentType.CENTER, keepNext: true, spacing: { before: 200, after: 80 },
    children: [new ImageRun({ type: "png", data: fs.readFileSync(file),
      transformation: { width: w, height: Math.round(w * px[1] / px[0]) } })] }));
}

const TITLE = "Validating a synthetic segmentation benchmark by rank correlation: how the methods compared, the clinical reference and training noise change the answer in wound imaging";

// ------------------------------------------------------------------ title
add(new Paragraph({ alignment: AlignmentType.LEFT, spacing: { after: 160, line: 300 },
  children: [new TextRun({ text: TITLE, font: L.FONT, size: 30, bold: true, color: L.INK })] }));
add(rule(220));

// ------------------------------------------------------------------ abstract
part = "abstract";
H2("Abstract");
P("Synthetic test sets for medical image segmentation are often validated by showing that they rank methods like a clinical dataset. We measured how this correlation depends on the methods compared, the clinical reference and training noise. We scored {{n.ALL}} methods on {{d.nref}} public clinical datasets in {{w.nmod}} modalities and on synthetic wound images: {{n.U}} untrained classical methods, {{n.F}} methods trained from scratch on wound photographs, the same {{n.K}} trained on colonoscopy, and {{n.M19}} modern models ({{n.pre}} ImageNet-pretrained architectures with up to three training seeds, and nnU-Net). Agreement was the Spearman correlation of per-method mean Dice. Pooling classical and modern methods made four wound datasets agree at {{a.dice.UM19.wound}}, although they agreed at {{a.dice.U.wound}} among the classical and {{a.dice.M19.wound}} among the modern methods. A synthetic benchmark agreed with the wound datasets at {{b.UM19.mean.bench}} over the pooled methods but at {{b.M19.mean.bench}} among the modern models, where it could not be shown to be better or worse than another wound dataset. Two training seeds of the same architectures agreed at only {{sd.rbar}} on the same wound dataset. The model ranked first on the test set from the training clinic lost {{sel.fus.row}} Dice on other wound datasets, against {{sel.fus.rand}} for a random choice. On the AZH dataset the pretrained models, run on images resized to {{d.lb}} pixels, missed {{miss.P18.azh}} of wounds on average, against {{miss.nn.azh}} for nnU-Net at native resolution. Validity should be reported within the group of methods to be compared, against several clinical datasets.");
part = "front";
P("**Keywords** Benchmark validity; Rank agreement; Synthetic data; Wound imaging; Image segmentation; Training variance", { after: 200 });

// ------------------------------------------------------------------ introduction
part = "main";
H1("Introduction");
P("Segmentation software is increasingly evaluated before it reaches a clinic, by vendors comparing candidate models, by hospitals validating a product on local data and by regulators considering computational evidence. Synthetic and simulated images are attractive for this purpose because they come with exact ground truth and can be generated in any quantity, and in-silico trials and edited images have already been used to evaluate and stress-test medical models [@badano2018;@sizikova2023;@tushar2026a;@perezgarcia2024]. Rankings of segmentation methods are, however, known to be fragile. They change with the test cases, the metric, the aggregation rule and the annotators [@maierhein2018;@reinke2024;@urooj2026], with the choice of benchmark [@dehghani2021;@pierard2025] and with the hospital the test data come from [@bassi2024;@ali2024].");
P("The usual evidence that a synthetic test set is trustworthy is a rank correlation between method scores on the synthetic set and on one clinical dataset, sometimes expressed relative to the agreement between two real datasets [@kang2022;@borsukiewicz2026]. Synthetic data have been proposed for model validation and selection on a similar basis [@hu2023;@vanbreugel2023;@shoshan2023], and in computed tomography (CT) the transfer of rankings from synthetic to real data has been shown to depend on the task [@tushar2026b]. Such a correlation is computed over a particular set of methods, which we call the method pool, and we call a benchmark's rank agreement with clinical data its measured validity. Outside medical imaging it is established that agreement between benchmarks depends on which models are compared [@perlitz2024], and that the correlation between in-distribution and out-of-distribution performance depends on how the models were selected and trained [@teney2023;@miller2021;@fang2022]. When groups of methods change order between domains, pooling them produces correlations that hold in neither group, a form of Simpson's paradox [@simpson1951;@kievit2013].");
P("Medical segmentation studies often pool exactly such groups. Wound segmentation work, for example, spans classical colour and threshold methods and trained networks [@zhang2022], and recent wound studies compare several deep architectures across datasets [@lucho2024;@benfatah2026]. A synthetic benchmark validated over a pool that mixes such groups inherits whatever the pooling does to the correlation. A second source of variation lies in training itself. Retraining the same network with another random seed changes its score, and for closely matched models these changes can be as large as the differences between models [@bouthillier2021;@varoquaux2022]. A ranking of modern models on one dataset may then be partly a ranking of training runs, and training noise limits how closely two datasets can be expected to agree on an order. Decision thresholds add a further choice, because networks differ in how confident their outputs are [@guo2017]. How large these effects are for segmentation, and what they imply for validating a synthetic benchmark, has not been measured.");
P("We scored {{n.ALL}} methods in four groups, each with one training regime, on {{d.nref}} clinical datasets from {{w.nsrc}} sources in {{w.nmod}} modalities and on synthetic wound benchmarks from three generator families. The modern group contains {{n.pre}} ImageNet-pretrained architectures, each trained with up to three random seeds, and nnU-Net. We asked how much pooling groups of methods changes agreement between clinical datasets, whether agreement is organised by modality within groups, how much of the disagreement among modern models is training noise, and what this implies for the measured validity of a synthetic benchmark and for choosing a model. The contributions are:");
list([
  "A measurement of the composition effect in segmentation benchmark agreement. Pooling untrained with modern methods raises agreement between wound datasets from {{a.dice.U.wound}} and {{a.dice.M19.wound}} within the groups to {{a.dice.UM19.wound}}, and an exact identity shows that ranking methods within their groups before pooling returns the size-weighted average of the within-group agreements.",
  "A demonstration that the measured validity of a synthetic benchmark follows the method pool and the clinical reference: the same benchmark agrees with wound data at {{b.UM19.mean.bench}} or at {{b.M19.mean.bench}} depending on whether untrained methods are in the pool, and its agreement with single wound datasets varies within one pool.",
  "Evidence from {{n.pre}} architectures with up to three training seeds that rankings of modern models on wound data are dominated by small differences and training noise, with the consequences for model selection, including selection on a test set from the training clinic, and a failure mode on one dataset that mean Dice hides.",
]);

// ------------------------------------------------------------------ methods
H1("Materials and Methods");
H2("Clinical datasets");
P("{{w.nref.cap}} public datasets serve as clinical references (Table 1). The wound photographs are Medetec [@medetec2014], CO2Wounds-V2 [@sanchez2024], the validation set of the Foot Ulcer Segmentation (FUSeg) challenge [@wang2024] and the AZH chronic wound dataset [@wang2020]. FUSeg and AZH were collected at one wound centre and are treated as one source; CO2Wounds-V2 contains {{c.co2.n}} smartphone photographs from {{c.co2.pat}} leprosy patients in Colombia [@sanchez2024] and shares no source with any other dataset. The colonoscopy datasets are Kvasir-SEG [@jha2020] and its sessile subset, CVC-ClinicDB [@bernal2015], CVC-ColonDB [@bernal2012] and ETIS-LaribPolypDB [@silva2014]; the two CVC sets come from one group and are one source. PH2 [@mendonca2013] is the dermoscopy reference and the TN3K test split [@gong2021] the thyroid ultrasound reference. A disjoint slice of the AZH training set serves as a within-dataset control.", { after: 100 });
P("The FUSeg reference is the first {{d.n.fus}} validation images and the AZH reference the first {{d.n.azh}} test images, sorted by file name; Medetec is used in full. The Kvasir reference was drawn only from images outside the sessile subset, so the two Kvasir references share no image. For CO2Wounds-V2 and the five other non-wound datasets, {{d.nsample}} image and mask pairs were taken evenly spaced over the files sorted by number, because consecutive colonoscopy frames are near duplicates. Images in these six sets were resampled so that the long side is at most {{d.maxside}} pixels; wound masks were binarised at any non-zero value and all others above {{d.bin}}. Several images can come from one photograph: Medetec's {{n.img.med}} images are {{n.unit.med}} photographs with four variants each, and the {{n.img.azh}} AZH test images and {{n.img.ctrl}} control images are crops of {{n.unit.azh}} and {{n.unit.ctrl}} photographs. The photograph is therefore the resampling unit for these three sets in every analysis, and the image for all others.", { after: 100 });
P("Duplicated and overlapping evaluation images were removed before any analysis. In FUSeg, {{n.excl.fus}} validation images are byte-identical to FUSeg training images ({{n.excl.fus.train}}) or to another validation image ({{n.excl.fus.eval}}). FUSeg and AZH come from the same clinic, so every AZH test image and every control image was compared with all {{sift.fus.n}} FUSeg photographs ({{sift.fus.train}} training, {{sift.fus.val}} validation) by feature matching: scale-invariant feature transform (SIFT) keypoints, a ratio test at {{sift.ratio}}, and a similarity transform fitted by random sample consensus (RANSAC), with at least {{sift.min}} geometrically consistent keypoints counting as a match. The rule for removal was the same for every set: an evaluation image was removed if it is a copy or a crop of a photograph used elsewhere in this study, that is a FUSeg training image used for training or threshold tuning, or an image of another evaluation set. Of the {{ov.azh.n}} AZH test images, {{ov.azh.match}} are crops of FUSeg photographs; {{ov.azh.used}} of these were cut from training images and were removed, and the other {{ov.azh.unused}} come from FUSeg photographs that no model saw and that are not among the FUSeg reference images, so they were kept, leaving {{n.img.azh}}. Of the {{n.ctrl.before}} control images, {{n.excl.ctrl.crop}} are crops of FUSeg photographs used in this study ({{n.excl.ctrl.train}} from its training split and {{n.excl.ctrl.val}} from the validation images used as reference), and {{n.excl.ctrl.azhdup}} more are pixel-identical to AZH test images; they were removed, leaving {{n.img.ctrl}}. {{w.ctrl.unused.cap}} further control image is a crop of a FUSeg photograph used nowhere in the study (a duplicate removed from both the training and the reference images) and was kept. A fifth wound dataset (WoundSeg) was prepared but excluded before any method was scored on it, because {{ws.bad}} of its {{ws.n}} masks did not match the size of their image, so the pairing of images and masks could not be trusted. The exclusions and the overlap check are listed in Online Resource 1 (Tables S9a and S9e).");
cap("Table", 1, "Clinical datasets after removal of duplicated and overlapping images. Units are the resampling units (photographs for Medetec and the AZH sets, images otherwise). Lesion fraction is the median share of image pixels inside the reference mask");
const DS = [
  ["Medetec", "Wound photography", "Medetec archive", "med"],
  ["CO2Wounds-V2", "Wound photography", "Leprosy clinic, Colombia", "co2"],
  ["FUSeg (validation)", "Wound photography", "AZH Wound Center", "fus"],
  ["AZH (test)", "Wound photography", "AZH Wound Center", "azh"],
  ["AZH train slice (control)", "Wound photography", "AZH Wound Center", "ctrl"],
  ["Kvasir", "Colonoscopy", "Kvasir collection", "kva"],
  ["Kvasir-sessile", "Colonoscopy", "Kvasir collection", "kvs"],
  ["CVC-ClinicDB", "Colonoscopy", "CVC, Barcelona", "cvc1"],
  ["CVC-ColonDB", "Colonoscopy", "CVC, Barcelona", "cvc2"],
  ["ETIS-Larib", "Colonoscopy", "ETIS, Paris", "etis"],
  ["PH2", "Dermoscopy", "Porto", "ph2"],
  ["TN3K (test)", "Thyroid ultrasound", "TN3K", "tn3k"],
];
T(["Dataset", "Modality", "Source", "Images", "Units", "Empty masks", "Lesion fraction"],
  DS.map(([a, b, c, k]) => [a, b, c, `{{n.img.${k}}}`, `{{n.unit.${k}}}`, `{{n.empty.${k}}}`, `{{frac.${k}}}`]),
  [2150, 1750, 1950, 750, 700, 950, 1110], { leftCols: 3 });

H2("Method groups");
P("The {{n.ALL}} methods form four groups that differ in training and in training domain (Table 2; every method is listed in Online Resource 1, Table S1). The {{n.U}} untrained methods (U) are classical thresholding, colour, clustering and region-growing algorithms with no learned parameters. The {{n.F}} from-scratch methods (F) are three pixel classifiers (two logistic regressions and gradient boosting on colour and texture features), a three-level U-Net with {{d.unet.params}} parameters, and ten architectures from segmentation_models_pytorch [@iakubovskii2019] with randomly initialised encoders. These ten are U-Net [@ronneberger2015], U-Net++ [@zhou2018], DeepLabV3+ [@chen2018], FPN [@lin2017], PSPNet [@zhao2017], LinkNet [@chaurasia2017] and MA-Net [@fan2020] on ResNet-18 [@he2016], U-Net on MobileNetV2 [@sandler2018] and EfficientNet-B0 [@tan2019], and SegFormer on MiT-B0 [@xie2021].", { after: 100 });
P("The from-scratch group was trained on FUSeg training images. The pixel classifiers were fitted on {{d.px.n}} pixels sampled from images {{d.px.img}}, balanced between lesion and background. The threshold of one logistic regression was tuned on images {{d.px.thrimg}} (best value {{d.px.thr}}), and this value was used for all three pixel classifiers. The small U-Net uses a threshold of {{d.unet.thr}}. The ten architectures were trained on images {{d.tr.img}} at {{d.fs.size}} by {{d.fs.size}} pixels for {{d.fs.ep}} epochs (Dice plus binary cross-entropy, Adam, learning rate {{d.fs.lr}}, horizontal flips), and each threshold was tuned on images {{d.thr.img}}. The Kvasir-trained group (K) repeats this protocol exactly on Kvasir-SEG images that appear in neither Kvasir reference nor the sessile subset (pixel threshold {{d.kv.thr}}).", { after: 100 });
P("The modern group (M19) contains {{n.pre}} architectures with ImageNet-pretrained encoders [@deng2009] and nnU-Net. Ten are the architectures of the from-scratch group with pretrained encoders. Eight were added to cover larger encoders and current designs: U-Net, DeepLabV3+ and MA-Net on ResNet-50, U-Net on EfficientNet-B3 [@tan2019] and on Swin-T [@liu2021], SegFormer on MiT-B2 [@xie2021], UPerNet [@xiao2018] on ConvNeXt-T [@liu2022] and FPN on RegNetY-1.6GF [@radosavovic2020]. All {{n.pre}} were trained with one protocol on FUSeg training images {{d.tr.img}} with the one image duplicated in the evaluation set removed ({{n.train}} of the {{sift.fus.train}} FUSeg training images). Images were letterboxed so that the long side is {{d.lb}} pixels, with the aspect ratio kept and the remainder padded with black pixels. Training used Dice plus binary cross-entropy, AdamW (learning rate {{d.pt.lr}}, weight decay {{d.pt.wd}}, cosine decay), batches of {{d.pt.batch}}, {{ep.pre}} epochs, random horizontal and vertical flips and rotations by multiples of a right angle, and mixed-precision arithmetic with gradient scaling. Each model's decision threshold was chosen on a grid from {{d.grid}} in steps of {{d.grid.step}} to maximise mean Dice on {{n.sweep}} held-out FUSeg training images (images {{d.thr.img}} without two duplicates of evaluation images); this held-out Dice is optimistic, because the threshold was tuned on the same images. Held-out Dice of the {{n.pre.models}} individual models ranged from {{ho.pre}}.", { after: 100 });
P("Each architecture was trained with three random seeds ({{d.seeds}}). The seed sets the initial weights of the parts not taken from ImageNet, the order of the training batches and the augmentation draws. Seed {{d.seed0}} of the ten original architectures was trained in a first session on a graphics processing unit (GPU); seeds {{d.seeds12}} of these and all seeds of the eight new architectures were trained in a second session with the same training code. The second session recorded segmentation_models_pytorch {{ver.smp}}, timm {{ver.timm}} and PyTorch {{ver.torch}}; the first did not record the PyTorch and timm versions. Of the {{n.run2}} trainings in the second session, {{n.run2.ok}} produced a usable model. The {{n.run2.fail}} that did not were MA-Net trainings ({{n.manet.fail}} of {{n.manet.run2}}: ResNet-18 at seed {{d.seed2}} and ResNet-50 at seeds {{d.seeds02}}), in which mixed-precision arithmetic produced non-finite values; the other {{n.other.run2}} trainings had none. Failed trainings were not imputed. In the main analyses each architecture is represented by the per-image mean of its scores over the seeds that exist (its seed average), so MA-Net on ResNet-18 averages two models and MA-Net on ResNet-50 is a single model.", { after: 100 });
P("nnU-Net v2 [@isensee2021] was trained once, in its 2D configuration with the default trainer, on all {{n.train}} training images (one model, no cross-validation folds) for {{d.nn.ep}} epochs instead of the default {{c.nn.ep.default}}. Its foreground probability is thresholded at {{d.nn.thr}}; its Dice on the {{n.sweep}} held-out images is {{ho.nn}}. To produce inputs for the robustness analyses nnU-Net was run again in the second session on the same images. Per-image Dice differed from the first run by at most {{nn.img.maxdiff}} and dataset means by at most {{nn.mean.maxdiff}}, with no change of rank, so all main analyses use the first-run scores (Online Resource 1, Table S9b).", { after: 100 });
P("The Segment Anything Model (SAM) [@kirillov2023] and its medical version MedSAM [@ma2024] were also run, with box prompts taken from the reference masks. Because those prompts give them the lesion location, they are reported only in Online Resource 1 (Table S8) and are not part of any method set.", { after: 100 });
P("In the main post-processing pipeline (P0), untrained methods receive morphological closing and opening with a {{d.pp.elem}}-pixel elliptical element. Methods that output a probability map receive Gaussian smoothing with a standard deviation of {{d.pp.sigma}} pixels before thresholding. Every method then has connected components smaller than {{d.pp.minarea}} of the image removed.");
cap("Table", 2, "Method groups. Mean Dice is the range of group means (mean over methods of the per-method mean) over the four wound datasets and over the seven other clinical datasets");
T(["Group", "n", "Training data", "Training seeds", "Mean Dice, wound", "Mean Dice, other"],
  [
    ["Untrained (U)", "{{n.U}}", "none", "none", "{{md.U.wound}}", "{{md.U.other}}"],
    ["From scratch (F)", "{{n.F}}", "FUSeg", "one", "{{md.F.wound}}", "{{md.F.other}}"],
    ["Kvasir-trained (K)", "{{n.K}}", "Kvasir-SEG", "one", "{{md.K.wound}}", "{{md.K.other}}"],
    ["Modern (M19)", "{{n.M19}}", "FUSeg, ImageNet encoders", "up to three per architecture; one for nnU-Net", "{{md.M19.wound}}", "{{md.M19.other}}"],
  ],
  [1800, 500, 2100, 2000, 1480, 1480], { leftCols: 4 });

H2("Synthetic benchmarks");
P("Three parametric generator families produce wound images with exact masks, {{d.syn.n}} images per benchmark in three severity classes. Generator A places a lesion on a uniform drape and reproduces the benchmark released with an earlier system description [@islam2026]. Generator B renders textured skin with clutter such as hair and gauze, and its background texture amplitude is a parameter; it was built at amplitudes {{d.amps}}. Generator C shares no code with B and uses spectral noise, vignetting and a colour mixture model. Every benchmark was built at three synthetic seeds ({{d.synseeds}}). Background texture is the median local standard deviation of shading-corrected luminance in a {{d.tex.win}}-pixel window over background pixels, measured at {{d.tex.res}} pixels.");

H2("Agreement between image sets");
P("Each method is scored per image with the Dice similarity coefficient (Dice) between its mask and the reference mask. Agreement between two image sets is the Spearman correlation between their vectors of per-method mean Dice over a given set of methods: a rank correlation, so {{d.one}} means that the two image sets order the methods identically and {{d.zero}} means no relation. The {{n.pairs}} pairs of the {{d.nref}} clinical datasets are grouped by level: within source (one clinic or group, no shared images; {{n.pairs.src}} pairs), within modality from different sources ({{n.pairs.dsrc}} pairs) and across modality ({{n.pairs.across}} pairs). The within-dataset control compares AZH with the disjoint AZH slice. The modality difference is mean same-modality agreement ({{n.pairs.same}} pairs) minus mean across-modality agreement ({{n.pairs.across}} pairs). For the composition analyses each pair is assigned to one of four categories relative to a domain, the modality a trained group was trained on. For wound photography these are domain with domain (the {{n.pairs.wound}} wound pairs, whose mean we call wound-pair agreement), domain with other datasets ({{n.pairs.w_out}} pairs), other datasets of the same modality (the {{n.pairs.colon}} colonoscopy pairs) and other datasets across modality ({{n.pairs.oacross}} pairs). Method sets are the four groups alone and the pooled sets U+F ({{n.UF}} methods), U+K ({{n.UK}}) and U+M19 ({{n.UM19}}). Every analysis was repeated with normalised surface Dice (NSD), the share of the predicted and reference boundaries that lie within a tolerance of each other, at {{d.nsd.tau}} pixels [@nikolov2021], and with the images whose reference mask is empty excluded.", { after: 100 });
P("Pairs share datasets, so tests on pairs overstate the evidence. The modality difference was therefore tested by assigning the modality labels to the {{d.nref}} datasets in every distinct way ({{n.relabel}} assignments) and counting how often the difference was at least as large as observed. Swapping the labels of the two single-dataset modalities gives the same partition of pairs, so the smallest attainable p is $2/${{n.relabel}} = {{p.min}}. Because the three within-source pairs could carry the result alone, the test was repeated with them dropped under every relabelling ({{n.pairs52}} pairs). The test treats the method set and the images as fixed. For pooled sets it shows that pooling produces apparent modality structure, not evidence that such structure exists.", { after: 100 });
P("Two bootstrap designs give {{d.ci}} percentile intervals. The method bootstrap resamples methods with replacement within each group, so a pooled set keeps its composition ({{d.B.method}} draws). These intervals show how much agreement depends on which methods of each kind are included, treating the methods as a sample of comparable methods. Spearman correlations use average ranks for ties, which occur when a method is drawn more than once; with {{n.N7}} to {{n.M19}} methods a draw contains few distinct methods, so these intervals are approximate. The hierarchical bootstrap also resamples the units of every dataset independently ({{d.B.hier}} draws for the clinical and seed analyses; {{d.B.hier.bench}} for the synthetic-benchmark analyses, which also resample the synthetic images), using photographs as units for Medetec ({{n.unit.med}} photographs), AZH ({{n.unit.azh}}) and the control ({{n.unit.ctrl}}), and images for the other datasets. Resampling units adds noise to every method mean and so pulls a single agreement value towards zero in each draw. Hierarchical intervals are therefore conservative for claims that a single agreement value exceeds zero, but not for claims that agreement is low, and not for differences in which one term shares images across seeds (see the training-seed analyses). Intervals in the text are method-bootstrap intervals unless marked hierarchical; miss-rate intervals resample units only, and seed-analysis intervals resample architectures. Analyses of the synthetic benchmarks that involve untrained or from-scratch methods use the method bootstrap only, because per-image synthetic scores exist only for the GPU-trained groups. Image sampling within a dataset was also summarised by split-half reliability, an estimate of how well a new set of images from the same dataset would rank the methods again: the Spearman correlation between method means on two random halves of the units, corrected with the Spearman-Brown formula (median of {{d.splits}} splits).");

H2("Stratified agreement and why it equals the within-group average");
P("Stratified agreement ranks methods within their own group first and then pools them. Within each group $g$ of size $n_{g}$, a method's mean on a dataset is replaced by its within-group percentile $(r − 0.5)/n_{g}$, where $r$ is its rank in the group, and agreement is the Pearson correlation of these percentiles over the pooled set of $N = Σ n_{g}$ methods. The percentiles have mean $1/2$ in every group, so the pooled mean is also $1/2$ and the between-group part of the pooled covariance is zero. The pooled covariance of the percentiles on datasets A and B is therefore $(1/N) Σ n_{g} c_{g}$, and each pooled variance is $(1/N) Σ n_{g} v_{g}$, where $c_{g}$ and $v_{g}$ are the covariance and variance within group $g$. Without ties, $v_{g} = (1 − 1/n_{g}^{2})/12$ on every dataset, and within a group the correlation of percentiles is the Spearman correlation $r_{g}$. Hence", { after: 60 });
P("$stratified agreement = Σ_{g} w_{g} r_{g} / Σ_{g} w_{g},  with  w_{g} = n_{g} − 1/n_{g},$", { align: AlignmentType.CENTER, after: 60 });
P("a size-weighted average of the within-group agreements: the pooled within-group correlation, applied to within-group ranks. The weights do not depend on the pair, so the identity also holds for means over pairs. It holds exactly when no two methods in a group have the same mean on either dataset. With ties, each group is weighted by $n_{g}$ times the square root of its two percentile variances, and the weights then depend on the pair. In our data ties occur only on TN3K and PH2; there the Pearson value differs from the weighted average by at most {{rv.ident.maxpair}} for a single pair and by at most {{rv.ident.maxmean}} for a mean over pairs, and for the wound pairs the identity is exact. Stratified agreement thus adds no information beyond the within-group agreements; what it shows is how much of a pooled value comes from differences in level between groups. Ranking the pooled percentiles again (a Spearman version) changed single pairs by at most {{s.maxpair}} under Dice.");

H2("Training-seed analyses");
P("In total {{n.C16}} architectures have all three seeds: nine of the original ten and seven of the eight new ones. The two MA-Net architectures lack seeds and nnU-Net has one training, so these three are left out of the seed analyses. For each wound dataset, same-dataset cross-seed agreement is the mean Spearman correlation between the architecture means of seeds s and t on the same images, over the three seed pairs. Its counterpart across datasets correlates seed s on one wound dataset with a different seed t on another ({{n.cross36}} correlations over the {{n.pairs.wound}} wound pairs), so that training noise is present in both and only the dataset differs. The gap between the two measures how much more two datasets disagree than two trainings scored on the same images do. Because the two seeds share their test images, the gap also contains image-sampling noise and is an upper bound on the part of the disagreement due to the datasets; and because both seeds share one resample of units in each hierarchical draw, hierarchical intervals for the gap are shifted upwards rather than towards zero. We also compared wound-pair agreement at single seeds (mean over the three seeds) with agreement of the seed averages, and set the spread of architecture means on each dataset against the seed-to-seed standard deviation of one architecture's mean (pooled over the {{n.C16}} architectures). The reliability of an architecture's mean Dice was summarised by a one-way random-effects intraclass correlation (ICC) over the {{n.C16}} architectures: with W the mean seed variance and T the variance of the three-seed means minus $W/3$, the ICC is $T/(T + W)$ for one seed and T divided by the variance of the three-seed means for a three-seed average. Intervals resample architectures ({{d.B.arch}} draws); hierarchical intervals also resample units ({{d.B.hier}} draws).", { after: 100 });
P("One reading rule was written down after the new models had been trained and scored, but before any seed analysis was run (the pre-specified rule). The statement that modern models disagree across wound datasets because the datasets differ, not because of training noise, would be supported if same-dataset cross-seed agreement exceeded {{c.rule.hi}} while cross-dataset agreement stayed near {{c.rule.lo}}. If cross-seed agreement were as low as cross-dataset agreement, the modern models would be treated as not distinguishable. Details are in Online Resource 1 (Table S4).");

H2("Synthetic benchmark analyses");
P("For each wound reference, benchmark agreement is the Spearman correlation between generator B at amplitude {{d.amp.hi}} and that reference, averaged over the three synthetic seeds. It is compared with the mean agreement of the other three wound datasets with the same reference; the difference (benchmark minus other) is positive when the benchmark ranks methods more like the reference than another wound dataset does. Averaged over the four references, the second term equals wound-pair agreement. The texture effect is benchmark agreement at amplitude {{d.amp.hi}} minus agreement at amplitude {{d.amp.lo}}. Benchmark agreement was also computed for single-seed versions of the original architectures, of the new architectures and of the full modern group, in which every architecture is represented by its model at one training seed; only the full single-seed modern group also includes nnU-Net.");

H2("Model selection and failure modes");
P("For the modern models, the selection loss from dataset A to dataset B is the best mean Dice on B minus the mean Dice on B of the candidate ranked first on A. The expected loss of a random choice is the mean over candidates of the best mean Dice minus the candidate's. The candidates are the seed-averaged architectures and nnU-Net, and, because a seed average is not the output of any model, also the single-seed models of each training seed. The synthetic chooser picks the candidate with the highest mean Dice on generator B (mean over synthetic seeds). Selection losses are small Dice differences and are given to three decimals; their intervals resample the units of each dataset with the candidates fixed ({{rv.sel.B}} draws). A miss is a non-empty reference mask segmented with Dice below {{d.miss}}. Miss rates were computed for every individual trained model and averaged over seeds per architecture; their intervals resample units ({{d.B.unit}} draws) with the models fixed. To look for the cause of the misses on AZH we related, for each image, the share of pretrained models that miss it to its share of black padding pixels (every colour channel at most {{d.black}}) and to its lesion fraction, and we measured from the feature matches the scale of AZH crops relative to the FUSeg photographs they were cut from.");

H2("Robustness analyses");
P("The main analyses were repeated with two other post-processing pipelines (P1: threshold, closing and opening with a {{d.pp.elem}}-pixel element and small-component removal; P2: threshold and small-component removal only), with NSD at tolerances of {{d.nsd.tols}}, and with FUSeg resampled so that its long side is {{d.maxside}} pixels, the resolution of most other datasets. For the modern models the threshold protocol was also varied: one common threshold for all models (each value of the grid from {{d.grid}}), and a per-dataset oracle threshold for every model, chosen on the evaluation images themselves to reduce calibration differences, that is differences between models in the level of their output probabilities. These reanalyses used probability maps rescored in the second session; for the pooled sets the untrained and from-scratch methods were rescored locally with the same variants. Three Kvasir-trained pixel classifiers were not rescored, so robustness results for the Kvasir group use the remaining {{n.K11}} methods (Online Resource 1, Table S6).");

H2("Primary and exploratory analyses");
P("Two analyses were planned as primary. The composition effect was assessed with the paired method-bootstrap interval of pooled agreement minus the higher within-group agreement, and the modality structure within groups with the exact relabelling test. The modern group was redefined from {{n.M}} to {{n.M19}} methods when the additional trainings became available, before the analyses reported here were run. With {{rv.holm.nsets}} method sets tested, every modality difference in Table 3 remains significant at the {{d.alpha}} level after Holm correction (largest adjusted p {{rv.holm.max}}). All other analyses, including the training-seed, benchmark, selection and robustness analyses, are exploratory; they are reported with intervals and are not corrected for multiple comparisons.");
P("Large language model assistants were used to write analysis code and to draft and edit the text; all code, numbers and text were checked by the authors.");

// ------------------------------------------------------------------ results
H1("Results");
H2("The groups differ in level and in domain");
P("The groups differ in level and in domain (Table 2). The modern models reach group mean Dice of {{md.M19.wound}} on the wound datasets but {{md.M19.other}} on the seven other datasets, and the from-scratch group shows the same pattern at a lower level. The Kvasir-trained group leads on colonoscopy ({{md.K.colon}}) and is close to the untrained group on wound photographs ({{md.K.wound}} against {{md.U.wound}}). We call a group mean Dice below {{d.floor}} on a dataset the floor, because rankings there order near-zero scores. With the trained models fixed, each dataset ranks the methods reproducibly across its images: split-half reliability within the untrained, from-scratch and Kvasir-trained groups is {{rv.rel.UFK}} on the {{d.nref}} datasets, and {{rel.M19.wound}} for the modern models on the four wound datasets. This reliability does not include retraining.");

H2("Pooling creates agreement and disagreement");
P("Pooling the untrained group with the modern group changes agreement in both directions (Fig. 1a, Table 3). Over the pooled {{n.UM19}} methods the four wound datasets agree at {{a.dice.UM19.wound}} ({{a.dice.UM19.wound.m}}), against {{a.dice.U.wound}} ({{a.dice.U.wound.m}}) among untrained methods and {{a.dice.M19.wound}} ({{a.dice.M19.wound.m}}) among modern models; the pooled value exceeds the higher of the two by {{rp.UM19.gap.P0}} ({{rp.UM19.gap.P0.m}}). Agreement between wound and other datasets becomes {{a.dice.UM19.w_in_out}} ({{a.dice.UM19.w_in_out.m}}), against {{a.dice.U.w_in_out}} and {{a.dice.M19.w_in_out}} within the groups, and non-wound datasets of different modalities appear to agree at {{a.dice.UM19.w_out_across}} ({{a.dice.UM19.w_out_across.m}}), against {{a.dice.U.w_out_across}} and {{a.dice.M19.w_out_across}}. Under NSD the pooled wound-pair agreement is {{a.nsd.UM19.wound}}, against {{a.nsd.U.wound}} and {{a.nsd.M19.wound}} within the groups. The full agreement matrices are shown in Online Resource 1 (Fig. S1).", { after: 100 });
P("The from-scratch group moves agreement in the same direction by less (Fig. 1b). Pooled with the untrained methods, wound datasets agree at {{a.dice.UF.wound}}, against {{a.dice.U.wound}} and {{a.dice.F.wound}} within the groups, but the excess over the untrained group, {{rp.UF.gap.P0}}, has an interval that includes zero ({{rp.UF.gap.P0.m}}). Agreement between wound and other datasets turns negative, {{a.dice.UF.w_in_out}} ({{a.dice.UF.w_in_out.m}}), against {{a.dice.U.w_in_out}} and {{a.dice.F.w_in_out}} within the groups.", { after: 100 });
P("The mechanism is visible in the group means. The modern models lead the untrained methods on every wound dataset and fall below them on every other dataset (Table 2; per-dataset means in Online Resource 2), so a pooled correlation between a wound and a non-wound dataset is dominated by which group each method belongs to, without any pair of methods changing order within a group. The Kvasir-trained group is the mirror experiment. It leads on colonoscopy, but on wound photographs its means ({{md.K.wound}}) are close to those of the untrained methods ({{md.U.wound}}), so the two groups do not change places across modalities. Pooling it with the untrained group pulls agreement between colonoscopy and other datasets below both groups ({{a.dice.UK.c_in_out}}, against {{a.dice.U.c_in_out}} and {{a.dice.K.c_in_out}}) but does not reverse its sign (Fig. 1c).", { after: 100 });
P("Stratified agreement removes the effect and, as derived in the Methods, equals the size-weighted average of the within-group agreements. For U+M19 the stratified wound-pair agreement is {{s.dice.UM19.wound}} (size-weighted within-group average {{rv.ident.UM19.sw}}; pooled {{s.dice.UM19.wound.pool}}), and the stratified modality difference is {{s.dice.UM19.mdiff}}, against {{s.dice.UM19.mdiff.pool}} pooled. For U+F and U+K the stratified modality differences are {{s.dice.UF.mdiff}} and {{s.dice.UK.mdiff}}, against {{s.dice.UF.mdiff.pool}} and {{s.dice.UK.mdiff.pool}} pooled.");
